300:     Client.prototype._send = function (request, track, callback) {
301: 
302:         callback = callback || ignore;
303: 
304:         if (!this._ws ||
305:             this._ws.readyState !== WS.OPEN) {
306: 
307:             return callback(new Error('Failed to send message - server disconnected'));
308:         }
309: 
310:         request.id = ++this._ids;
311: 
312:         stringify(request, (err, encoded) => {
313: 
314:             if (err) {
315:                 return callback(err);
316:             }
317: 
318:             // Ignore errors
319: 
320:             if (!track) {
321:                 try {
322:                     return this._ws.send(encoded);
323:                 }
324:                 catch (err) {
325:                     return callback(err);
326:                 }
327:             }
328: 
329:             // Track errors
330: 
331:             const record = {
332:                 callback: callback,
333:                 timeout: null
334:             };
335: 
336:             if (this._settings.timeout) {
337:                 record.timeout = setTimeout(() => {
338: 
339:                     record.callback = null;
340:                     record.timeout = null;
341: 
342:                     return callback(new Error('Request timed out'));
343:                 }, this._settings.timeout);
344:             }
345: 
346:             this._requests[request.id] = record;
347: 
348:             try {
349:                 this._ws.send(encoded);
350:             }

